//! Makes the embedded schema a real build input.
//!
//! `include_str!` already gets recorded in rustc's dependency info, so an edit
//! to the generated files does trigger a rebuild. This states it outright
//! anyway, and turns a missing file into a sentence rather than a macro error
//! pointing inside a crate the reader did not write.
//!
//! Deliberately does *not* regenerate. Regenerating would need Node, and the
//! whole point of the CLI is that it does not. The schema is generated by
//! Zellij, committed, and verified in CI — see `.github/workflows/ci.yml`,
//! which fails if the committed copy has fallen behind the engine.

use std::path::Path;

fn main() {
    for file in ["generated/schema.json", "generated/context.md"] {
        println!("cargo::rerun-if-changed={file}");

        if !Path::new(file).exists() {
            panic!(
                "{file} is missing.\n\
                 It is generated by the engine, not written by hand:\n\n    \
                 node engine/packages/zellij/bin/zellij.mjs context \
                 cli/crates/zellij-core/{file}{}\n",
                if file.ends_with(".json") {
                    " --json"
                } else {
                    ""
                }
            );
        }
    }
}
